import { Group } from 'three/webgpu';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const group = new Group();

  // Store timelines and primitive cleanups for later disposal
  const timelines = [];
  const primitiveCleanups = [];

  // Load GLB mesh (if provided) and add to the group
  const meshUrl = config.meshUrl;
  if (meshUrl) {
    ctx.glbLoader.loadGLB(meshUrl).then((gltf) => {
      group.add(gltf.scene);
    });
  }

  // Apply any cinematic primitives defined in the config
  if (Array.isArray(config.cematicPrimitives)) {
    config.cinematicPrimitives.forEach((prim) => {
      const fn = ctx.primitives[prim.name];
      if (fn) {
        const result = fn(group, prim.params);
        if (result?.timeline) timelines.push(result.timeline);
        if (typeof result?.cleanup === 'function') primitiveCleanups.push(result.cleanup);
      }
    });
  }

  // Event handlers (attached to userData.handlers)
  const handlers = {};

  // Hover effect: rise-in (subtle, 0.15 scene units)
  handlers.hover = (enter) => {
    const targetY = enter ? group.position.y + 0.15 : group.position.y - 0.15;
    const tl = gsap.timeline({ paused: false });
    tl.to(group.position, { y: targetY, duration: 0.7, ease: 'power3.out' });
    timelines.push(tl);
  };

  // Click effect: emit navigation event
  handlers.click = () => {
    ctx.emit('hub-home.select', {});
  };

  group.userData.handlers = handlers;

  // Cleanup routine
  group.userData.cleanup = () => {
    // Kill all GSAP timelines
    timelines.forEach((t) => t.kill());
    // Run primitive cleanups
    primitiveCleanups.forEach((fn) => fn());

    // Dispose geometries and materials in the group
    group.traverse((obj) => {
      if (obj.isMesh) {
        if (obj.geometry) obj.geometry.dispose();
        if (obj.material) {
          if (Array.isArray(obj.material)) {
            obj.material.forEach((m) => m.dispose());
          } else {
            obj.material.dispose();
          }
        }
      }
    });
  };

  return group;
}
